tool_input.content:
$ErrorActionPreference = 'Stop'
Set-Location D:\repository\skills\cursor-model-routing
$tasks = Get-Content .\tasks.json -Raw -Encoding UTF8 | ConvertFrom-Json
function Head($s,$n=110){ if($s.Length -gt $n){$s.Substring(0,$n)}else{$s} }
function OffTask($s){ return ($s -match '第\s*\d+\s*轮|【ID】|【Title】|【Difficulty】|SkillUpgradeTracker|skill-upgrade|面试题|###\s*助手|##\s*助手') }
function Call($model,$prompt){
  $body = @{ model = $model; messages = @(@{ role = 'user'; content = $prompt }); max_tokens = 1024; temperature = 0.2 } | ConvertTo-Json -Depth 8
  $sw=[System.Diagnostics.Stopwatch]::StartNew()
  try{ $resp=Invoke-RestMethod -Uri "http://127.0.0.1:3425/v1/chat/completions" -Method Post -Body $body -ContentType 'application/json' -TimeoutSec 300
    $sw.Stop(); $u=$resp.usage; return [pscustomobject]@{ok=$true;ms=$sw.ElapsedMilliseconds;pt=[int]$u.prompt_tokens;ct=[int]$u.completion_tokens;content=$resp.choices[0].message.content} }
  catch{ $sw.Stop(); return [pscustomobject]@{ok=$false;ms=$sw.ElapsedMilliseconds;pt=0;ct=0;content="ERR: $($_.Exception.Message)"} }
}
$out=@()
foreach($tid in @('T5','T7b')){
  $prompt=($tasks.tasks|Where-Object{$_.id -eq $tid}).prompt
  foreach($rep in 1..3){
    $r=Call 'cursor/grok-4.7@256k' $prompt
    $off=OffTask $r.content
    Write-Output ("grok-4.7@256k {0} rep{1} ok={2} {3}ms pt={4} ct={5} offTask={6} clen={7}" -f $tid,$rep,$r.ok,$r.ms,$r.pt,$r.ct,$off,$r.content.Length)
    Write-Output ("   head: " + ((Head $r.content) -replace "`n"," "))
    $out += [pscustomobject]@{model='cursor/grok-4.7@256k';task=$tid;rep=$rep;ok=$r.ok;ms=$r.ms;pt=$r.pt;ct=$r.ct;off_task=$off;clen=$r.content.Length;content=$r.content}
  }
}
$out | ConvertTo-Json -Depth 6 | Set-Content .\results\grok-repro.json -Encoding UTF8
Write-Output "wrote results/grok-repro.json"

$ErrorActionPreference = 'Stop'
Set-Location D:\repository\skills\cursor-model-routing
# 离线验证"跑题正则"：对已有 results 语料打标 + 算 precision/recall
# 标注口径：已知 off-task 的样本（人工确认），其余 on-task。标注只依据我们实际读过的内容。

$rows = @()
foreach($f in @('primary','gift','t3-repro','composer-repro','t7b','grok-repro','smoke')){
  $p = "results/$f.json"
  if(Test-Path $p){
    $data = Get-Content $p -Raw -Encoding UTF8 | ConvertFrom-Json
    foreach($r in @($data)){ if($r.model -and $r.content -ne $null){ $rows += [pscustomobject]@{src=$f;model=$r.model;task=$r.task;content=[string]$r.content} } }
  }
}
Write-Output "total samples: $($rows.Count)"

# ---- 人工标注 ground truth（依据实际读取内容）----
# 已知 off-task 判定：模板坍缩特征
function GroundTruth($r){
  $c = $r.content
  # composer T3 初测那次跑到 SkillUpgradeTracker -> off
  if($r.model -eq 'cursor/composer-2.5' -and $r.task -eq 'T3' -and $r.src -eq 'primary' -and $c -match 'SkillUpgradeTracker|skill-upgrade'){ return $true }
  # composer T7b 单次跑成 第18/19/20轮 -> off
  if($r.model -eq 'cursor/composer-2.5' -and $r.task -eq 'T7b' -and $c -match '第\s*1[89]\s*轮|第\s*20\s*轮'){ return $true }
  # composer-repro T3 rep3 输出"前端面试题" -> off
  if($r.model -eq 'cursor/composer-2.5' -and $r.task -eq 'T3' -and $r.src -eq 'composer-repro' -and $c -match '面试题|【Title】'){ return $true }
  return $false
}

# ---- 正则（跑题检测器）----
$PATTERN = '第\s*\d+\s*轮|【ID】|【Title】|【Difficulty】|SkillUpgradeTracker|skill-upgrade-tracker|前端面试题|面试题|#{1,3}\s*助手\s*$|#{1,3}\s*用户\s*$'
function Predict($c){ return ($c -match $PATTERN) }

$tp=0;$fp=0;$tn=0;$fn=0
$mistakes=@()
foreach($r in $rows){
  $truth = GroundTruth $r
  $pred  = Predict $r.content
  if($truth -and $pred){$tp++}
  elseif(-not $truth -and $pred){$fp++; $mistakes += "FP: $($r.src)/$($r.model)/$($r.task)"}
  elseif(-not $truth -and -not $pred){$tn++}
  else{$fn++; $mistakes += "FN: $($r.src)/$($r.model)/$($r.task) content_head=" + ($r.content.Substring(0,[math]::Min(80,$r.content.Length)) -replace "`n"," ")}
}
$prec = if($tp+$fp -gt 0){[math]::Round(100.0*$tp/($tp+$fp),1)}else{0}
$rec  = if($tp+$fn -gt 0){[math]::Round(100.0*$tp/($tp+$fn),1)}else{0}
Write-Output "TP=$tp FP=$fp TN=$tn FN=$fn"
Write-Output "Precision=$prec%  Recall=$rec%"
Write-Output "=== mistakes ==="
$mistakes | ForEach-Object { Write-Output $_ }

