# composer T3 初测那次跑到 SkillUpgradeTracker -> off
if($r.model -eq 'cursor/composer-2.5' -and $r.task -eq 'T3' -and $r.src -eq 'primary' -and $c -match 'SkillUpgradeTracker|skill-upgrade'){ return $true }
# t3-repro rep3 输出"前端面试题"模板 -> off
if($r.src -eq 't3-repro' -and $c -match '【ID】|【Title】|前端面试题'){ return $true }

# 主池 / 赠额分组（按用户口径）
$PRIMARY = @('cursor/composer-2.5','cursor/grok-4.7@256k','cursor/grok-4.7@500k','cursor/grok-4.6','cursor/grok-4.5')
$GIFT    = @('cursor/deepseek-v41-flash-1017','cursor/kimi-k3','cursor/kimi-k2.7-code','cursor/glm-5p3','cursor/glm-5.2','cursor/glm-5p3-flash')

# 跑题（模板坍缩）检测正则。离线验证见 REPORT §6b.2（100% precision/recall @ 78 样本，正类 3）。
# 用法：composer 输出先过此正则，命中即判可疑（拒收→重跑或升级 grok）。
$script:OFFTASK_PATTERN = '第\s*\d+\s*轮|【ID】|【Title】|【Difficulty】|SkillUpgradeTracker|skill-upgrade-tracker|前端面试题|面试题|#{1,3}\s*助手\s*$|#{1,3}\s*用户\s*$'
function Test-OffTask {
  param([string]$Text)
  if ([string]::IsNullOrEmpty($Text)) { return $false }
  # 只扫头部 200 字，降低成本（坍缩特征几乎都在开头）
  $head = if ($Text.Length -gt 200) { $Text.Substring(0, 200) } else { $Text }
  return ($Text -match $script:OFFTASK_PATTERN)  # 全文匹配更稳；如需降本可改 $head
}
